export function dataRecord(value,keys){if(!value||typeof value!=='object'||Object.getPrototypeOf(value)!==Object.prototype)return null;const actual=Reflect.ownKeys(value);if(actual.length!==keys.length||actual.some(k=>typeof k!=='string'||!keys.includes(k)))return null;const out={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(value,k);if(!d||!d.enumerable||!Object.hasOwn(d,'value'))return null;out[k]=d.value}return out}
export function denseBooleanPair(value){if(!Array.isArray(value)||Object.getPrototypeOf(value)!==Array.prototype)return false;const keys=Reflect.ownKeys(value);if(keys.length!==3||!keys.includes('0')||!keys.includes('1')||!keys.includes('length'))return false;const len=Object.getOwnPropertyDescriptor(value,'length');if(!len||len.value!==2)return false;for(const k of['0','1']){const d=Object.getOwnPropertyDescriptor(value,k);if(!d||!d.enumerable||!Object.hasOwn(d,'value')||typeof d.value!=='boolean')return false}return true}
export function validatedState(s,revision){const d=dataRecord(s,['revision','aObserved','bBits','cObserved','cProgress','cOpen','epoch']);if(!d||d.revision!==revision||typeof d.aObserved!=='boolean'||!Number.isInteger(d.bBits)||d.bBits<0||d.bBits>7||!denseBooleanPair(d.cObserved)||!Number.isInteger(d.cProgress)||d.cProgress<0||d.cProgress>3||typeof d.cOpen!=='boolean'||d.cOpen!==(d.cProgress===3)||!Number.isSafeInteger(d.epoch)||d.epoch<0||d.epoch>=Number.MAX_SAFE_INTEGER||(!d.aObserved&&d.bBits!==0)||d.cProgress&&(!d.aObserved||!d.cObserved[0]||!d.cObserved[1]))return null;return d}
